#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/drivers/modem/modem_pipe.h>
#include <zephyr/sys/atomic.h>

/* Define test events as bits in an atomic variable */
#define TEST_MODEM_PIPE_EVENT_OPEN_READY_BIT    0
#define TEST_MODEM_PIPE_EVENT_CLOSED_BIT        1
#define TEST_MODEM_PIPE_EVENT_TRANSMIT_IDLE_BIT 2
#define TEST_MODEM_PIPE_EVENT_RECEIVE_READY_BIT 3
#define TEST_MODEM_PIPE_EVENT_ERROR_BIT         4

static atomic_t test_state;
static struct modem_pipe *test_pipe;
static K_SEM_DEFINE(pipe_event_sem, 0, 1); /* Semaphore to signal any event */

/* Callbacks for the modem pipe */
static void pipe_open_ready_cb(struct modem_pipe *pipe, int status)
{
    ARG_UNUSED(pipe);
    ARG_UNUSED(status);
    atomic_set_bit(&test_state, TEST_MODEM_PIPE_EVENT_OPEN_READY_BIT);
    k_sem_give(&pipe_event_sem);
}

static void pipe_closed_cb(struct modem_pipe *pipe, int status)
{
    ARG_UNUSED(pipe);
    ARG_UNUSED(status);
    atomic_set_bit(&test_state, TEST_MODEM_PIPE_EVENT_CLOSED_BIT);
    k_sem_give(&pipe_event_sem);
}

static void pipe_transmit_idle_cb(struct modem_pipe *pipe, int status)
{
    ARG_UNUSED(pipe);
    ARG_UNUSED(status);
    atomic_set_bit(&test_state, TEST_MODEM_PIPE_EVENT_TRANSMIT_IDLE_BIT);
    k_sem_give(&pipe_event_sem);
}

static void pipe_receive_ready_cb(struct modem_pipe *pipe, int status)
{
    ARG_UNUSED(pipe);
    ARG_UNUSED(status);
    atomic_set_bit(&test_state, TEST_MODEM_PIPE_EVENT_RECEIVE_READY_BIT);
    k_sem_give(&pipe_event_sem);
}

static void pipe_error_cb(struct modem_pipe *pipe, int status)
{
    ARG_UNUSED(pipe);
    ARG_UNUSED(status);
    atomic_set_bit(&test_state, TEST_MODEM_PIPE_EVENT_ERROR_BIT);
    k_sem_give(&pipe_event_sem);
}

static const struct modem_pipe_cb test_pipe_callbacks = {
    .open_ready = pipe_open_ready_cb,
    .closed = pipe_closed_cb,
    .transmit_idle = pipe_transmit_idle_cb,
    .receive_ready = pipe_receive_ready_cb,
    .error = pipe_error_cb,
};

static void test_modem_pipe_setup(void)
{
    test_pipe = modem_pipe_get_default(); /* Assuming a default pipe exists for testing */
    zassert_not_null(test_pipe, "Failed to get default modem pipe");
    modem_pipe_set_cb(test_pipe, &test_pipe_callbacks);
    atomic_set(&test_state, 0);
    k_sem_reset(&pipe_event_sem);
}

/* Test cases */

static void test_async_open_close(void)
{
    int ret;

    test_modem_pipe_setup();

    /* Open pipe */
    ret = modem_pipe_open(test_pipe, K_SECONDS(5));
    zassert_equal(ret, 0, "modem_pipe_open failed");

    /* Wait for open_ready callback */
    ret = k_sem_take(&pipe_event_sem, K_SECONDS(5));
    zassert_equal(ret, 0, "Timed out waiting for open_ready");
    zassert_true(atomic_test_bit(&test_state, TEST_MODEM_PIPE_EVENT_OPEN_READY_BIT),
                 "Open ready bit not set");

    /* Close pipe */
    atomic_clear_bit(&test_state, TEST_MODEM_PIPE_EVENT_OPEN_READY_BIT);
    k_sem_reset(&pipe_event_sem);
    ret = modem_pipe_close(test_pipe, K_SECONDS(5));
    zassert_equal(ret, 0, "modem_pipe_close failed");

    /* Wait for closed callback */
    ret = k_sem_take(&pipe_event_sem, K_SECONDS(5));
    zassert_equal(ret, 0, "Timed out waiting for closed");
    zassert_true(atomic_test_bit(&test_state, TEST_MODEM_PIPE_EVENT_CLOSED_BIT),
                 "Closed bit not set");
}

static void test_async_transmit(void)
{
    int ret;
    uint8_t tx_buf[] = "Hello Zephyr";

    test_modem_pipe_setup();

    /* Open pipe first */
    ret = modem_pipe_open(test_pipe, K_SECONDS(5));
    zassert_equal(ret, 0, "modem_pipe_open failed");
    ret = k_sem_take(&pipe_event_sem, K_SECONDS(5));
    zassert_equal(ret, 0, "Timed out waiting for open_ready");
    zassert_true(atomic_test_bit(&test_state, TEST_MODEM_PIPE_EVENT_OPEN_READY_BIT),
                 "Open ready bit not set");

    /* Clear state for transmit test */
    atomic_set(&test_state, 0);
    k_sem_reset(&pipe_event_sem);

    /* Transmit data asynchronously */
    ret = modem_pipe_transmit_async(test_pipe, tx_buf, sizeof(tx_buf));
    zassert_equal(ret, 0, "modem_pipe_transmit_async failed");

    /* Wait for transmit_idle callback */
    ret = k_sem_take(&pipe_event_sem, K_SECONDS(5)); /* This is the crucial wait */
    zassert_equal(ret, 0, "Timed out waiting for transmit_idle");

    /* Now check the state. The original assertion was likely here. */
    zassert_equal(atomic_get(&test_state), BIT(TEST_MODEM_PIPE_EVENT_TRANSMIT_IDLE_BIT),
                  "Expected only TRANSMIT_IDLE_BIT to be set");

    /* Close pipe */
    atomic_set(&test_state, 0);
    k_sem_reset(&pipe_event_sem);
    ret = modem_pipe_close(test_pipe, K_SECONDS(5));
    zassert_equal(ret, 0, "modem_pipe_close failed");
    ret = k_sem_take(&pipe_event_sem, K_SECONDS(5));
    zassert_equal(ret, 0, "Timed out waiting for closed");
    zassert_true(atomic_test_bit(&test_state, TEST_MODEM_PIPE_EVENT_CLOSED_BIT),
                 "Closed bit not set");
}

/* Define test suite */
ZTEST_SUITE(modem_pipe, NULL, NULL, NULL, NULL, NULL);

ZTEST_UNIT(modem_pipe, test_async_open_close);
ZTEST_UNIT(modem_pipe, test_async_transmit);
